import sys
from collections import defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    edges = []
    for i in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        edges.append((u, v, w, i))

    if m == n - 1:
        return

    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))

    def find(i):
        path = []
        while parent[i] != i:
            path.append(i)
            i = parent[i]
        for node in path:
            parent[node] = i
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j
            return True
        return False

    mst_edges = set()
    for u, v, w, idx in sorted_edges:
        if union(u, v):
            mst_edges.add(idx)

    adj = defaultdict(list)
    for u, v, w, idx in sorted_edges:
            if idx in mst_edges:
                adj[u].append((v, w))
                adj[v].append((u, w))

    results = [0] * m
    non_mst_indices = []

    for u, v, w, idx in edges:
        if idx not in mst_edges:
            non_mst_indices.append(idx)
            results[idx] = w

    def dfs(node, target, current_w, visited, stack):
        visited[node] = True
        if node == target:
            return current_w

        max_on_path = -1
        for neighbor, weight in adj[node]:
            if not visited[neighbor]:
                res = dfs(neighbor, target, weight, visited, stack)
                if res != -1:
                    max_on_path = max(max_on_path, res)

        return max_on_path

    for idx in non_mst_indices:
        u, v, w, _ = edges[idx]
        visited = [False] * (n + 1)
        max_weight = dfs(u, v, w, visited, [])
        if max_weight != -1:
            results[idx] = max_weight

    output_lines = []
    for i in range(m):
        if i not in mst_edges:
            output_lines.append(str(results[i]))

    sys.stdout.write('\n'.join(output_lines) + '\n')

if __name__ == "__main__":
    main()
